// Extract incoming webhook payload or provide comprehensive mock context for instant manual test execution for Aura Studio
const item = $input.first()?.json || {};
const body = item.body || item;

const isManualTest = !body.case_id;

const caseId = body.case_id || 'case_aura_101_hoodie';
const customerRequest = body.customer_request || 'Money debited for Heavyweight Boxy Hoodie (₹2,499) on Aura Studio via UPI (TXN_4829103_INR) but no confirmation order received.';
const evidence = body.evidence || {
  payment: {
    id: 'pay_aura_hoodie',
    payment_reference: 'TXN_4829103_INR',
    amount: 2499.00,
    currency: 'INR',
    status: 'SUCCESS'
  },
  order: null,
  product: {
    id: 'prod_hoodie_01',
    name: 'Heavyweight Boxy Hoodie',
    price: 2499.00,
    stock: 10
  },
  policy: {
    order_recovery_enabled: true,
    refund_enabled: true,
    refund_approval_required: true,
    refund_approval_threshold: 500.00
  }
};
const knowledge = body.knowledge || [
  {
    policy_topic: 'Order Recovery Policy',
    content: 'When payment succeeds and stock is available (>0), AI must propose order recovery to customer without double-charge.'
  }
];

return {
  case_id: caseId,
  customer_request: customerRequest,
  evidence: evidence,
  knowledge: knowledge,
  is_manual_test: isManualTest
};

// Resolve AI Core Decision Engine
// Architectural Principle: AI PROPOSES. CODE DECIDES.

const prevData = $node['Extract & Ingest Case Context'].json;
const cogneeResult = $input.first()?.json || {};

const caseId = prevData.case_id;
const customerRequest = prevData.customer_request;
const evidence = prevData.evidence || {};
const payment = evidence.payment;
const order = evidence.order;
const product = evidence.product;
const refund = evidence.refund;
const policy = evidence.policy || {};
const conflict = evidence.conflict;

let decision = 'CONFLICT_ESCALATE';
let proposedAction = 'ESCALATE';
let requiresConfirmation = false;
let requiresApproval = false;
let aiSummary = '';
let customerMessage = '';

// Decision Matrix
if (conflict) {
  decision = 'CONFLICT_ESCALATE';
  proposedAction = 'ESCALATE';
  aiSummary = `Deterministic mismatch detected: ${conflict}. Handoff packet prepared for human specialist.`;
  customerMessage = `Our system detected a discrepancy (${conflict}). A support specialist has been assigned to verify and resolve this manually.`;
} else if (payment && payment.status === 'SUCCESS' && order) {
  decision = 'SHOW_EXISTING_ORDER';
  proposedAction = 'CONFIRM_EXISTING_ORDER';
  aiSummary = `Payment of ₹${payment.amount} was verified and active order (${order.order_number}) is already linked on AURA STUDIO. No duplicate order created.`;
  customerMessage = `Good news! Your payment of ₹${payment.amount} is linked to order ${order.order_number}. The order is currently ${order.status}.`;
} else if (refund && ['PENDING', 'REQUESTED'].includes(refund.status)) {
  decision = 'TRACK_EXISTING_REFUND';
  proposedAction = 'CHECK_REFUND';
  aiSummary = `A refund of ₹${refund.amount} is already in progress (Provider Ref: ${refund.provider_reference || 'REF-ACTIVE'}). Tracking existing refund.`;
  customerMessage = `A refund of ₹${refund.amount} is currently being processed by your bank. We are monitoring it.`;
} else if (payment && payment.status === 'PENDING') {
  decision = 'PAYMENT_PENDING';
  proposedAction = 'SCHEDULE_RECHECK';
  aiSummary = `Payment TXN ${payment.payment_reference || 'PENDING'} is awaiting bank clearance. Scheduled background recheck.`;
  customerMessage = `Your payment of ₹${payment.amount} is still awaiting bank confirmation. We will automatically recheck in the background.`;
} else if (!payment || payment.status === 'NOT_FOUND') {
  decision = 'PAYMENT_NOT_FOUND_ESCALATE';
  proposedAction = 'ESCALATE';
  aiSummary = 'Payment provider returned NOT_FOUND for the referenced transaction. Escalated with customer claim.';
  customerMessage = 'Our payment provider could not locate a completed charge for this transaction. A support specialist has been assigned to inspect manual bank receipts.';
} else if (payment && payment.status === 'SUCCESS' && !order && product && (product.stock > 0)) {
  decision = 'OFFER_ORDER_RECOVERY';
  proposedAction = 'RECOVER_ORDER';
  requiresConfirmation = true;
  aiSummary = `Verified payment of ₹${payment.amount} for ${product.name} on AURA STUDIO. Order missing due to webhook timeout. Stock available (${product.stock} units). Proposing order recovery.`;
  customerMessage = `Your ₹${payment.amount} payment was confirmed by the payment provider. Your checkout on AURA STUDIO was saved. The ${product.name} is in stock. Would you like me to complete and recover your original purchase without any extra charge?`;
} else if (payment && payment.status === 'SUCCESS' && !order && product && (product.stock <= 0)) {
  const threshold = parseFloat(policy.refund_approval_threshold || 500.00);
  const needsApproval = parseFloat(payment.amount || 0) >= threshold && (policy.refund_approval_required !== false);
  decision = 'OFFER_REFUND';
  proposedAction = 'REQUEST_REFUND';
  requiresApproval = needsApproval;
  aiSummary = `Payment verified ₹${payment.amount}, but ${product.name} is out of stock on AURA STUDIO. Refund path selected. Manager approval required: ${needsApproval}.`;
  customerMessage = `Your payment of ₹${payment.amount} was verified, but ${product.name} is currently out of stock. A full refund has been initiated to your original payment method.${needsApproval ? ' (Pending manager review under store policy)' : ''}`;
} else {
  decision = 'CONFLICT_ESCALATE';
  proposedAction = 'ESCALATE';
  aiSummary = 'Inconclusive system evidence or conflicting transaction records. Preparing human handoff packet.';
  customerMessage = 'We encountered conflicting records while investigating your order. A specialist has been assigned with full investigation telemetry to resolve this directly.';
}

return {
  case_id: caseId,
  decision: decision,
  proposed_action: proposedAction,
  requires_customer_confirmation: requiresConfirmation,
  requires_approval: requiresApproval,
  ai_summary: aiSummary,
  customer_message: customerMessage,
  cognee_knowledge_applied: Array.isArray(cogneeResult) ? cogneeResult.length : 1,
  status: 'SUCCESS',
  timestamp: new Date().toISOString()
};

// Final formatting and output payload compliance
const proposal = $input.first().json;

return {
  status: proposal.status || 'SUCCESS',
  case_id: proposal.case_id,
  decision: proposal.decision,
  proposed_action: proposal.proposed_action,
  requires_customer_confirmation: proposal.requires_customer_confirmation,
  requires_approval: proposal.requires_approval,
  ai_summary: proposal.ai_summary,
  customer_message: proposal.customer_message,
  execution_verified: true,
  executed_at: proposal.timestamp
};
